class Stack
  def initialize
    @items = []
  end

  def push(value)
    @items << value
  end

  def pop
    @items.pop
  end
end

Result = Struct.new(:ok, :value, :error, keyword_init: true) do
  def self.ok(value) = new(ok: true, value: value, error: nil)
  def self.err(error) = new(ok: false, value: nil, error: error)
end
